/// <summary>
/// Logs errors to AppInsights.
/// </summary>
/// <param name="args">The arguments for the error method.</param>
[PreHandlerFor(classStr(Global), staticMethodStr(Global, error))]
public static void Global_Pre_error(XppPrePostArgs args)
{
    if(     !TFMParameters::find().TelemetryDisabled
        &&  !SysApplicationInsightsTelemetryHelper::overrideUseLegacyTelemetry()
        &&  strScan(con2Str(xSession::xppCallStack()), 'TFMDocumentConnector', 1, 2000))
    {
        SysApplicationInsightsExceptionTelemetry exceptionTelemetry = SysApplicationInsightsExceptionTelemetry::newFromExceptionMessage(Args.getArg('txt'));
        exceptionTelemetry.addProperty(SysApplicationInsightsClassNameProperty::newFromValue(classStr(Global)));
        exceptionTelemetry.addProperty(SysApplicationInsightsMethodNameProperty::newFromValue(staticmethodStr(Global, Error)));
        exceptionTelemetry.addProperty(SysApplicationInsightsCallStackProperty::newFromCurrentCallStack());
        exceptionTelemetry.addProperty(TFMAppInsightsFeatureNameProperty::newFromValue('TFM'));

        TFMAppInsightsTelemetryLogger::instance().trackException(exceptionTelemetry);
    }
}
